select * from ( select rep.REPORTUUID reportuuid, rep.TERMID termid, rep.REPORTTYPE reporttype, rep.STARTDATE startdate, rep.ENDDATE enddate, rep.ISSUE_PARTY_ID issuePartyId, rep.ISSUE_PARTY_NAME issuePartyName, rep.REPORTFREQU reportfrequ, rep.REPORT_ORG_NAME reportOrgName, rep.SOCIAL_CREDIT_CODE socialCreditCode, rep.FIN_INSTITUTION_CODE finInstitutionCode, rep.PROD_VARIETY prodVariety, rep.PERSON_LIABLE personLiable, rep.CONTACT contact, rep.REPORT_DATE reportDate, rep.SUBMIT_TIME submitTime, rep.CHB_SUBMIT_DEADLINE chbSubmitDeadline, rep.SUBMIT_DEADLINE submitDeadline, rep.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus, rep.STATUS status, rep.SEND_STATUS sendStatus, rep.STATUS_DATE statusDate, rep.CREATE_USER createUser, rep.CREATE_TIME createTime, rep.UPDATE_USER updateUser, rep.UPDATE_TIME updateTime, rep.ORG_CODE orgCode, rep.DEPT_CODE deptCode, rep.CREATE_DEPT createDept, ifnull(t2.pbc_code,rep.PBC_ACCOUNT_ID)PBC_ACCOUNT_ID, t2.PBC_CODE pbcCode, rep.PBC_ACCOUNT_ID pbcAccountIdShow, pra.ACCOUNT_ID accountId from PBC_REPORT rep left join PBC_PRD_ACCOUNT_SUB pra on pra.PBC_ACCOUNT_ID=rep.PBC_ACCOUNT_ID LEFT JOIN( SELECT inside_prod_id, pbc_code FROM pbc_prod_assetpool_code WHERE status='E' AND code_type='02' )t2 ON t2.inside_prod_id=pra.ACCOUNT_ID
#{items,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
#{items.pbcAccountId,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{item,jdbcType=VARCHAR}
#{submitFeedbackStatus,jdbcType=VARCHAR}
and DATE_FORMAT(rep.STATUS_DATE,'%Y-%m-%d') >= #{statusDateStart,jdbcType=VARCHAR}
and DATE_FORMAT(rep.STATUS_DATE,'%Y-%m-%d') <= #{statusDateEnd,jdbcType=VARCHAR}
and rep.termid >= #{submitDateStart,jdbcType=VARCHAR}
and rep.termid <= #{submitDateEnd,jdbcType=VARCHAR}
and DATE_FORMAT(rep.SUBMIT_TIME,'%Y-%m-%d') >= #{submitTimeStart,jdbcType=VARCHAR}
and DATE_FORMAT(rep.SUBMIT_TIME,'%Y-%m-%d') <= #{submitTimeEnd,jdbcType=VARCHAR}
AND DATE_FORMAT(rep.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') >= #{submitDeadLineStart,jdbcType=VARCHAR}
and DATE_FORMAT(rep.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') <= #{submitDeadLineEnd,jdbcType=VARCHAR}
and rep.termid = #{termid,jdbcType=VARCHAR}
and DATE_FORMAT(rep.UPDATE_TIME,'%Y-%m-%d') = #{updateTime}
and rep.CREATE_DEPT in ( select dept_code from sys_department sd1 where sd1.dept_code = #{createDept,jdbcType=VARCHAR} or sd1.upper_dept_code = #{createDept,jdbcType=VARCHAR} )
and rep.reporttype = 'ONEPRD_ASSET_DEBT'
) tmp
ORDER BY CHBSUBMITDEADLINE ASC, UPDATETIME DESC

